def import_books(loans, text):
    """Add the books of CSV `text` (isbn,title,authors,year) to `loans`'s
    catalog, the ones it has skipped: (added, skipped). A bad row adds
    nothing."""
    rows = csv.DictReader(io.StringIO(text))
    missing = [c for c in ("isbn", "title", "authors", "year") if c not in (rows.fieldnames or [])]
    if missing:
        raise ValueError(f"missing columns: {', '.join(missing)}")
    books = []
    for row in rows:
        if not any((v or "").strip() for v in row.values()):
            continue
        year = (row["year"] or "").strip()
        if year and not year.isdigit():
            raise ValueError(f"not a year: {year!r}")
        authors = [a.strip() for a in (row["authors"] or "").split(";") if a.strip()]
        books.append(Book(row["isbn"].strip(), row["title"].strip(), authors, int(year) if year else None))
    added = skipped = 0
    for book in books:
        if book.isbn in loans.catalog.books:
            skipped += 1
        else:
            loans.catalog.add(book)
            added += 1
    return added, skipped


